# Karty těles: věta pro děti (Oliver, 3 roky – krátce, obrazně) a pro dospělé (fakta). Údaje podle Wikipedie a NASA.
F = {
 'Borisov': ('Kometa Borisov přiletěla od jiné hvězdy. Jen proletěla a už se nevrátí.', 'Druhý známý mezihvězdný návštěvník (2019), první mezihvězdná kometa. Objevil ji amatér Gennadij Borisov vlastním dalekohledem. Výstřednost dráhy 3,36 – nejvíc ze všech známých těles.'),
 'West': ('Westova kometa měla obrovský vějíř ohonu. Byla vidět i ve dne.', 'Velká kometa roku 1976. U Slunce se jí jádro rozpadlo na čtyři kusy. Vrátí se nejdřív za statisíce let.'),
 'Ikeya-Seki': ('Tahle kometa proletěla těsně nad Sluncem a zářila jako Měsíc.', 'Nejjasnější kometa 20. století (1965), jasnost až −10 mag. Patří do Kreutzovy rodiny komet „lízajících“ Slunce: prolétla 450 000 km nad jeho povrchem.'),
 'McNaught': ('McNaughtova kometa měla ohon jako páví ocas přes půl oblohy.', 'Velká kometa roku 2007, nejjasnější za 40 let (−5,5 mag), viditelná za denního světla. Nejlépe ji viděli na jižní polokouli.'),
 'Lovejoy': ('Kometa Lovejoy proletěla sluneční koronou a přežila.', 'Sluneční „lízač“ z Kreutzovy rodiny (2011). Prolétla jen 140 000 km nad povrchem Slunce při teplotě přes milion °C a vynořila se bez ohonu, který jí hned dorostl.'),
 'Bennett': ('Bennettova kometa byla jednou z nejkrásnějších komet minulého století.', 'Velká kometa roku 1970. Poprvé u ní družice zjistila obrovský oblak vodíku kolem hlavy – větší než Slunce.'),
 'Arend-Roland': ('Tahle kometa měla dva ohony: jeden mířil ke Slunci!', 'Velká kometa roku 1957 se slavným „protichvostem“ – úzkým hrotem zdánlivě namířeným ke Slunci (prach v rovině dráhy viděný z boku).'),
 'Kirch (Great Comet of 1680)': ('První kometa objevená dalekohledem. Pomohla Newtonovi pochopit gravitaci.', 'Objevil ji Gottfried Kirch roku 1680. Isaac Newton na její dráze ověřil, že se komety řídí stejnou gravitací jako planety.'),
 'NEAT': ('Kometu NEAT vyfotila sonda, když letěla těsně kolem Slunce.', 'C/2002 V1 prolétla roku 2003 zorným polem sluneční observatoře SOHO, zrovna když ji zasáhl výron sluneční hmoty.'),
 'Duende': ('Duende je balvan velký jako dům. Proletěl kolem Země blíž než televizní družice.', 'Planetka 2012 DA14 (~30 m). 15. 2. 2013 minula Zemi o 27 700 km – pod drahou geostacionárních družic. Ten samý den dopadl nesouvisející čeljabinský meteor.'),
 'Sisyphus': ('Sisyfos je největší planetka, která kříží dráhu Země.', 'Největší planetka typu Apollo (~8,5 km) – velká asi jako těleso, které vyhubilo dinosaury. Má malý měsíček. Zemi neohrožuje.'),
 'Eugenia': ('Eugenia má vlastní měsíček. Jmenuje se Malý princ.', 'Planetka hlavního pásu (~190 km) se dvěma měsíci; první, Petit-Prince, byl objeven roku 1998 ze Země pomocí adaptivní optiky.'),
 'Elektra': ('Elektra má tři měsíčky – nejvíc ze všech planetek.', 'První známá čtyřnásobná planetka: tři měsíce objevené v letech 2003, 2014 a 2021.'),
 'Astraea': ('Astraeu objevil pošťák, který hledal planetky 15 let.', 'Pátá objevená planetka (1845). Karl Hencke, poštovní úředník a amatér, jí ukončil 38leté čekání od objevu Vesty.'),
 'Sun': ('Slunce je obrovská hvězda. Svítí a hřeje celou Sluneční soustavu.', 'Koule žhavého plynu (73 % vodíku, 25 % helia), v jádru 15 milionů °C. Světlo k Zemi letí 8 min 20 s. Otočka rovníku 25 dní, u pólů 35 dní.'),
 'Mercury': ('Merkur je nejmenší planeta a je nejblíž Slunci. Ve dne je tam horko a v noci mráz.', 'Den 430 °C, noc −180 °C. Den tam (od poledne do poledne) trvá 176 pozemských dní. Obří pánev Caloris má průměr 1 550 km.'),
 'Venus': ('Venuše je zahalená do mraků. Je to nejteplejší planeta, ještě teplejší než Merkur.', 'Tlak 92 barů, teplota 465 °C (skleníkový efekt CO₂). Točí se pozpátku a jedna otočka trvá déle než její rok (243 vs. 225 dní). Mraky z kyseliny sírové.'),
 'Earth': ('Země je náš domov. Modrá planeta s oceány, mraky a životem.', 'Poloměr 6 371 km, 71 % povrchu kryjí oceány. Jediné známé těleso se životem a s kapalnou vodou na povrchu. Osa skloněná o 23,4° dělá roční období.'),
 'Moon': ('Měsíc obíhá kolem Země. Na Měsíci se dá skákat jako klokan.', 'Poloměr 1 737 km, tíže 1/6 pozemské. K Zemi je natočen stále stejnou stranou. Na povrchu bylo 12 lidí (Apollo 1969–1972).'),
 'Mars': ('Mars je červená planeta. Je červený, protože má na povrchu rez.', 'Olympus Mons (22 km) je nejvyšší sopka Sluneční soustavy, kaňon Valles Marineris je 4 000 km dlouhý. Tíže 0,38 g, atmosféra z CO₂ (0,6 % tlaku Země). Den 24 h 37 min.'),
 'Phobos': ('Phobos je malý brambůrkovitý měsíc Marsu. Pomalu padá k Marsu.', 'Rozměry 27 × 22 × 18 km. Oběhne Mars za 7 h 39 min, rychleji, než se Mars otočí – vychází na západě. Za ~50 milionů let ho Mars roztrhá.'),
 'Deimos': ('Deimos je ještě menší měsíc Marsu.', 'Rozměry 15 × 12 × 11 km, oběh 30,3 h. Povrch je hladší, krátery zasypal prach.'),
 'Ceres': ('Ceres je trpasličí planeta mezi Marsem a Jupiterem.', 'Největší těleso pásu asteroidů (průměr 940 km). Sonda Dawn našla světlé skvrny solí v kráteru Occator a horu Ahuna Mons.'),
 'Vesta': ('Vesta je velký asteroid s obrovským kráterem na jižním pólu.', 'Kráter Rheasilvia má průměr 505 km a centrální horu vysokou ~22 km. Úlomky Vesty dopadají na Zemi jako meteority (HED).'),
 'Jupiter': ('Jupiter je největší planeta. Má obrovskou červenou skvrnu – je to bouře větší než Země.', 'Hmotnost 318 Zemí, otočka 9 h 56 min. Velká rudá skvrna je bouře pozorovaná přes 190 let. Pásy mraků z amoniaku, magnetické pole nejsilnější mezi planetami.'),
 'Io': ('Io má spoustu sopek. Je žlutá a oranžová jako pizza.', 'Nejvulkaničtější těleso Sluneční soustavy (~400 činných sopek). Teplo dodává slapové hnětení Jupiterem v rezonanci 1 : 2 : 4 s Europou a Ganymedem.'),
 'Europa': ('Europa je ledový měsíc. Pod ledem má ukrytý obrovský oceán.', 'Ledová kůra 15–25 km, pod ní slaný oceán se dvakrát víc vodou než všechny pozemské oceány. Jeden z nejnadějnějších cílů hledání života (Europa Clipper).'),
 'Ganymede': ('Ganymed je největší měsíc. Je větší než planeta Merkur.', 'Průměr 5 268 km, jako jediný měsíc má vlastní magnetické pole. Pod ledem slaný oceán. Cíl sondy JUICE.'),
 'Callisto': ('Callisto je měsíc posetý krátery jako sítko.', 'Nejstarší a nejvíc kráterovaný povrch ve Sluneční soustavě. Kráter Valhalla má soustředné valy přes 3 800 km.'),
 'Amalthea': ('Amalthea je malý červený měsíc blízko Jupiteru.', 'Protáhlý tvar 250 × 146 × 128 km, nejčervenější těleso Sluneční soustavy. Oběh 12 h.'),
 'Saturn': ('Saturn má krásné prstence z ledu a kamínků.', 'Prstence jsou široké 280 000 km, ale tlusté jen desítky metrů. Saturn má nejnižší hustotu (0,69 g/cm³ – plaval by ve vodě). Otočka 10 h 33 min.'),
 'Mimas': ('Mimas má obří kráter, takže vypadá jako Hvězda smrti.', 'Kráter Herschel má průměr 139 km, třetinu průměru Mimasu. Mimas čistí Cassiniho dělení v prstencích (rezonance 2 : 1).'),
 'Enceladus': ('Enceladus je sněhově bílý a stříká z něj voda do vesmíru.', 'Gejzíry u jižního pólu (tygří pruhy) chrlí vodu z podpovrchového oceánu a tvoří prstenec E. Odráží 99 % světla.'),
 'Tethys': ('Tethys je ledový měsíc s dlouhou prasklinou.', 'Kaňon Ithaca Chasma je 2 000 km dlouhý, kráter Odysseus 445 km. Hustota téměř jako voda (0,98 g/cm³).'),
 'Dione': ('Dione má na jedné straně ledové útesy.', 'Světlé „pruhy“ na odvrácené polokouli jsou ledové útesy vysoké stovky metrů. Na dráze má trojské měsíce Helene a Polydeuces.'),
 'Rhea': ('Rhea je druhý největší měsíc Saturnu, ledový a plný kráterů.', 'Průměr 1 527 km, povrch ze zmrzlé vody. Možná má řídký prstenec.'),
 'Titan': ('Titan má hustý oranžový vzduch a jezera, ale ne z vody – z metanu.', 'Atmosféra 1,45 baru (dusík), −179 °C. Jezera a moře z kapalného metanu a etanu (Kraken Mare). Huygens přistál 2005, Dragonfly poletí 2028.'),
 'Hyperion': ('Hyperion vypadá jako houba.', 'Pórovitý (hustota 0,54), chaoticky se převaluje. Krátery hluboké a ostré.'),
 'Iapetus': ('Iapetus má jednu stranu černou a druhou bílou.', 'Přední polokoule tmavá jako uhlí, zadní bílá jako sníh. Na rovníku hřbet vysoký až 20 km (vlašský ořech).'),
 'Phoebe': ('Phoebe obíhá Saturn pozpátku, daleko od ostatních.', 'Nejspíš zachycené těleso z Kuiperova pásu. Z prachu Phoebe vzniká obrovský prstenec Phoebe.'),
 'Uranus': ('Uran se kutálí po dráze – leží na boku.', 'Sklon osy 98°: každý pól má 42 let den a 42 let noc. Modrozelenou barvu dává metan. Nejchladnější atmosféra planet (−224 °C).'),
 'Miranda': ('Miranda vypadá jako poskládaná ze střípků.', 'Útes Verona Rupes je vysoký asi 20 km – nejvyšší známý útes ve Sluneční soustavě. Povrch jako slepenec (korony).'),
 'Ariel': ('Ariel je nejsvětlejší měsíc Uranu.', 'Mladý povrch s kaňony; nejméně kráterů z velkých měsíců Uranu.'),
 'Umbriel': ('Umbriel je nejtmavší měsíc Uranu.', 'Starý tmavý povrch, kráter Wunda s jasným prstencem na dně.'),
 'Titania': ('Titania je největší měsíc Uranu.', 'Průměr 1 578 km, kaňony dlouhé až 1 500 km (Messina Chasmata).'),
 'Oberon': ('Oberon je vnější velký měsíc Uranu.', 'Krátery s tmavým dnem, hora vysoká asi 11 km na okraji.'),
 'Neptune': ('Neptun je modrá větrná planeta. Fouká tam nejsilnější vítr.', 'Vítr až 2 100 km/h. Objeven výpočtem (Le Verrier, Galle 1846). Oběhne Slunce za 165 let.'),
 'Triton': ('Triton obíhá Neptun pozpátku a má gejzíry.', 'Retrográdní dráha – zachycené těleso z Kuiperova pásu. Dusíkové gejzíry, povrch „cantaloupe“. Teplota −235 °C.'),
 'Nereid': ('Nereida létá kolem Neptunu po velmi protáhlé dráze.', 'Výstřednost 0,75: vzdálenost od Neptunu se mění 1,4–9,6 milionu km.'),
 'Proteus': ('Proteus je hranatý měsíc Neptunu.', 'Jedno z největších nekulatých těles (420 km).'),
 'Pluto': ('Pluto je malá trpasličí planeta. Má na sobě ledové srdíčko.', 'Srdce Tombaugh Regio, ledovce z dusíku (Sputnik Planitia), hory z vodního ledu až 3,5 km. Modrá mlha. Proletěla kolem něj sonda New Horizons (2015).'),
 'Charon': ('Charon je Plutův velký kamarád. Točí se spolu jako na kolotoči.', 'Poloviční velikost Pluta; oba jsou k sobě natočené stále stejnou stranou. Červená čepička na pólu (tholiny).'),
 'Eris': ('Eris je trpasličí planeta daleko za Plutem.', 'Skoro stejně velká jako Pluto, ale hmotnější. Kvůli ní byl Pluto v roce 2006 přeřazen mezi trpasličí planety.'),
 'Haumea': ('Haumea je šišatá jako ragbyový míč a točí se jako vlček.', 'Otočka za 3,9 h – nejrychlejší z velkých těles. Má prstenec a dva měsíce (Hiʻiaka, Namaka).'),
 'Makemake': ('Makemake je trpasličí planeta pojmenovaná po bohovi z Velikonočního ostrova.', 'Povrch pokrytý metanovým ledem, načervenalý.'),
 'Sedna': ('Sedna je hodně daleko – jeden její rok trvá přes 11 000 let.', 'Afélium ~900 AU, perihélium 76 AU. Jedno z nejčervenějších těles.'),
 'Quaoar': ('Quaoar je ledový svět s prstencem, který by tam neměl být.', 'Prstenec daleko za Rocheovou mezí – záhada pro vědce.'),
 'Gonggong': ('Gonggong je vzdálený načervenalý svět.', 'Třetí až čtvrté největší transneptunické těleso, pomalá otočka 22 h.'),
 'Orcus': ('Orcus je „anti-Pluto“ – obíhá s ním v rezonanci, ale na druhé straně.', 'Rezonance 2 : 3 s Neptunem, měsíc Vanth.'),
 'Arrokoth': ('Arrokoth vypadá jako sněhulák ze dvou koulí.', 'Nejvzdálenější těleso navštívené sondou (New Horizons 2019). Dvě slepené části měkce spojené.'),
 'Bennu': ('Bennu je kamenitá hromádka sutě, ze které sonda nabrala vzorek.', 'OSIRIS-REx přivezla vzorek v roce 2023. Tvar „vlček“ s rovníkovým hřbetem, retrográdní otočka 4,3 h.'),
 'Ryugu': ('Ryugu je malý tmavý asteroid tvaru vlčku.', 'Hayabusa 2 odebrala vzorky (2020) a vystřelila do něj projektil.'),
 'Itokawa': ('Itokawa vypadá jako burský oříšek.', 'První asteroid se vzorkem na Zemi (Hayabusa 2010). Hromada suti, 535 m dlouhá.'),
 'Eros': ('Eros je protáhlý jako banán.', 'Na Erosu přistála sonda NEAR Shoemaker (2001) – první přistání na asteroidu.'),
 'Ida': ('Ida má svůj vlastní malý měsíček Dactyl.', 'První asteroid s objeveným měsícem (Galileo 1993).'),
 'Dactyl': ('Dactyl je malinký měsíček asteroidu Idy.', 'Průměr ~1,4 km, první objevený měsíc asteroidu.'),
 'Didymos': ('Didymos má malý měsíček Dimorphos, do kterého jsme schválně narazili sondou.', 'DART (2022) zkrátila oběh Dimorphosu o 33 minut – první test planetární obrany.'),
 'Dimorphos': ('Do Dimorphosu narazila sonda DART a změnila mu dráhu.', 'Průměr 151 m, po nárazu ztratil tvar a vytvořil ohon úlomků.'),
 'Apophis': ('Apophis proletí v roce 2029 hodně blízko kolem Země.', '13. dubna 2029 projde ve vzdálenosti ~32 000 km – blíž než geostacionární družice. Srážka nehrozí.'),
 'Psyche': ('Psyche je asteroid, který je možná z kovu.', 'Možná obnažené kovové jádro zaniklé planetky. Sonda Psyche k ní doletí v roce 2029.'),
 'Pallas': ('Pallas je velký asteroid se šikmou dráhou.', 'Sklon dráhy 35°, průměr 512 km.'),
 '1P/Halley (1986)': ('Halleyova kometa přilétá jednou za 76 let a má dlouhý ohon.', 'Naposledy 1986, příště 2061. Jádro 15 × 8 km, tmavé jako uhlí (Giotto). Z jejího prachu jsou meteory Orionidy a Eta Akvaridy.'),
 'Hale-Bopp': ('Kometa Hale-Bopp byla vidět na obloze přes rok.', 'Velká kometa 1997, jádro ~60 km. Viditelná pouhým okem 18 měsíců.'),
 '67P': ('Na kometu 67P přistál robot Philae.', 'Rosetta obíhala kometu 2014–2016. Tvar gumové kachničky, 4,1 × 3,3 km.'),
 '109P/Swift-Tuttle': ('Z prachu této komety jsou v srpnu padající hvězdy Perseidy.', 'Jádro ~26 km, oběh 133 let, příště 2126.'),
 '55P/Tempel-Tuttle': ('Z této komety jsou listopadové meteory Leonidy.', 'Oběh 33 let; při průletu bývají meteorické deště.'),
 '`Oumuamua': ('ʻOumuamua přiletěla z jiné hvězdy a zase odletí.', 'První známé mezihvězdné těleso (2017). Hyperbolická dráha, protáhlý tvar.'),
 'Chariklo': ('Chariklo je malé těleso, které má dva prstýnky.', 'První malé těleso s prstenci (2013), mezi Saturnem a Uranem.'),
 'Chiron': ('Chiron je napůl kometa a napůl asteroid.', 'Kentaur mezi Saturnem a Uranem, občas jeví kómu.'),
}
